--
-- Name: apply_leave_balance_usage(bigint); Type: FUNCTION; Schema: hrms; Owner: -
--

CREATE FUNCTION hrms.apply_leave_balance_usage(p_request_id bigint) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_req RECORD;
    v_balance_id int8;
    v_year int4;
    v_amount numeric(8,2);
BEGIN
    SELECT * INTO v_req FROM hrms.leave_request WHERE id = p_request_id;
    IF NOT FOUND THEN
        RETURN;
    END IF;

    v_year := EXTRACT(YEAR FROM v_req.start_datetime)::int4;
    v_amount := COALESCE(NULLIF(v_req.leave_days, 0), v_req.leave_hours);

    SELECT id INTO v_balance_id
    FROM hrms.leave_balance
    WHERE employee_id = v_req.employee_id
      AND leave_type_id = v_req.leave_type_id
      AND year = v_year
    FOR UPDATE;

    IF NOT FOUND THEN
        RETURN;
    END IF;

         'ตัดยอดจากคำขอลาเลขที่ ' || v_req.request_no);

    UPDATE hrms.leave_balance
    SET used_days = used_days + v_amount,
        remaining_days = remaining_days - v_amount
    WHERE id = v_balance_id;
END;
$$;


--
-- Name: capture_payroll_pre_approval_status(); Type: FUNCTION; Schema: hrms; Owner: -
--

CREATE FUNCTION hrms.capture_payroll_pre_approval_status() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.status = 'PENDING' AND OLD.status <> 'PENDING'
       AND NEW.document_type = 'PAYROLL_PERIOD' THEN
        UPDATE hrms.payroll_period
        SET pre_approval_status = OLD.status
        WHERE id = NEW.document_id;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: expire_leave_carry_forward(date); Type: FUNCTION; Schema: hrms; Owner: -
--

CREATE FUNCTION hrms.expire_leave_carry_forward(p_as_of_date date DEFAULT CURRENT_DATE) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_bal RECORD;
BEGIN
    FOR v_bal IN
        SELECT lb.id, lb.carry_forward_days
        FROM hrms.leave_balance lb
        JOIN hrms.leave_policy lp
          ON lp.leave_type_id = lb.leave_type_id
        WHERE lb.carry_forward_days > 0
          AND lp.carry_forward_expiry_months IS NOT NULL
          AND p_as_of_date >= (make_date(lb.year, 1, 1) + (lp.carry_forward_expiry_months || ' months')::interval)
    LOOP

        UPDATE hrms.leave_balance
        SET remaining_days     = remaining_days - carry_forward_days,
            carry_forward_days = 0
        WHERE id = v_bal.id;
    END LOOP;
END;
$$;


--
-- Name: fn_advance_approval_instance(); Type: FUNCTION; Schema: hrms; Owner: -
--

CREATE FUNCTION hrms.fn_advance_approval_instance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_instance RECORD;
    v_next_step RECORD;
BEGIN
    SELECT * INTO v_instance
    FROM hrms.approval_instance
    WHERE id = NEW.approval_instance_id
    FOR UPDATE;

    IF v_instance.status <> 'PENDING' THEN
        RETURN NEW;
    END IF;

    IF NEW.action_decision = 'REJECT' THEN
        UPDATE hrms.approval_instance
        SET status = 'REJECTED', completed_at = now()
        WHERE id = NEW.approval_instance_id;

    ELSIF NEW.action_decision = 'CANCEL' THEN
        UPDATE hrms.approval_instance
        SET status = 'CANCELLED', completed_at = now()
        WHERE id = NEW.approval_instance_id;

    ELSIF NEW.action_decision = 'APPROVE' THEN
        SELECT * INTO v_next_step
        FROM hrms.approval_step
        WHERE approval_flow_id = v_instance.approval_flow_id
          AND step_no > v_instance.current_step_no
        ORDER BY step_no
        LIMIT 1;

        IF v_next_step IS NULL THEN
            UPDATE hrms.approval_instance
            SET status = 'APPROVED', completed_at = now()
            WHERE id = NEW.approval_instance_id;
        ELSE
            UPDATE hrms.approval_instance
            SET current_step_no = v_next_step.step_no
            WHERE id = NEW.approval_instance_id;
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: fn_calculate_income_tax(numeric, date); Type: FUNCTION; Schema: hrms; Owner: -
--

CREATE FUNCTION hrms.fn_calculate_income_tax(p_annual_income numeric, p_calc_date date DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_bracket RECORD;
    v_tax numeric(15,2) := 0;
BEGIN
    IF p_annual_income IS NULL OR p_annual_income <= 0 THEN
        RETURN 0;
    END IF;

    SELECT * INTO v_bracket
    FROM hrms.tax_bracket
    WHERE status = 'ACTIVE'
      AND effective_from <= p_calc_date
      AND (effective_to IS NULL OR effective_to >= p_calc_date)
      AND income_from < p_annual_income
    ORDER BY income_from DESC
    LIMIT 1;

    IF v_bracket IS NULL THEN
        RETURN 0;
    END IF;

    v_tax := v_bracket.base_tax_amount + (p_annual_income - v_bracket.income_from) * v_bracket.tax_rate / 100;
    RETURN ROUND(v_tax, 2);
END;
$$;


--
-- Name: fn_calculate_payroll_formula(character varying, bigint, date); Type: FUNCTION; Schema: hrms; Owner: -
--

CREATE FUNCTION hrms.fn_calculate_payroll_formula(p_formula_code character varying, p_employee_id bigint, p_calc_date date DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
	v_formula_id bigint;
	v_item RECORD;
	v_result numeric(15,4) := NULL;
	v_value numeric(15,4);
BEGIN
	SELECT id INTO v_formula_id
	FROM hrms.payroll_calculation_formula
	WHERE formula_code = p_formula_code AND status = 'ACTIVE';

	IF NOT FOUND THEN
		RAISE EXCEPTION 'ไม่พบสูตร formula_code = %', p_formula_code;
	END IF;

	FOR v_item IN
		SELECT * FROM hrms.payroll_calculation_formula_item
		WHERE calc_formula_id = v_formula_id
		ORDER BY sequence_no
	LOOP
		v_value := hrms.fn_resolve_payroll_variable(v_item.variable_id, p_employee_id, p_calc_date);

		IF v_result IS NULL THEN
			v_result := v_value;
		ELSE
			v_result := CASE v_item.operation
				WHEN 'MULTIPLY' THEN v_result * v_value
				WHEN 'ADD'      THEN v_result + v_value
				WHEN 'SUBTRACT' THEN v_result - v_value
				WHEN 'DIVIDE'   THEN v_result / NULLIF(v_value, 0)
			END;
		END IF;
	END LOOP;

	RETURN ROUND(COALESCE(v_result, 0), 2);
END;
$$;


--
-- Name: fn_calculate_social_security(numeric, date); Type: FUNCTION; Schema: hrms; Owner: -
--

CREATE FUNCTION hrms.fn_calculate_social_security(p_monthly_wage numeric, p_calc_date date DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
    v_rate RECORD;
    v_base numeric(15,2);
BEGIN
    IF p_monthly_wage IS NULL OR p_monthly_wage <= 0 THEN
        RETURN 0;
    END IF;

    SELECT * INTO v_rate
    FROM hrms.social_security_rate
    WHERE status = 'ACTIVE'
      AND effective_from <= p_calc_date
      AND (effective_to IS NULL OR effective_to >= p_calc_date)
    ORDER BY effective_from DESC
    LIMIT 1;

    IF v_rate IS NULL THEN
        RETURN 0;
    END IF;

    v_base := LEAST(GREATEST(p_monthly_wage, v_rate.min_wage_base), v_rate.max_wage_base);
    RETURN ROUND(v_base * v_rate.employee_rate / 100, 2);
END;
$$;


