CREATE FUNCTION hrms.fn_force_sync_employee_master_text() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF NEW.gender_id IS NOT NULL THEN
        SELECT gender_name INTO NEW.gender FROM hrms.gender_type WHERE id = NEW.gender_id;
    ELSE
        NEW.gender := NULL;
    END IF;

    IF NEW.religion_id IS NOT NULL THEN
        SELECT religion_name INTO NEW.religion FROM hrms.religion WHERE id = NEW.religion_id;
    ELSE
        NEW.religion := NULL;
    END IF;

    IF NEW.marital_status_id IS NOT NULL THEN
        SELECT marital_status_name INTO NEW.marital_status FROM hrms.marital_status_type WHERE id = NEW.marital_status_id;
    ELSE
        NEW.marital_status := NULL;
    END IF;

    IF NEW.nationality_id IS NOT NULL THEN
        SELECT nationality_name INTO NEW.nationality FROM hrms.nationality WHERE id = NEW.nationality_id;
    ELSE
        NEW.nationality := NULL;
    END IF;

    RETURN NEW;
END;
$$;


