--
-- Name: fn_resolve_payroll_variable(bigint, bigint, date); Type: FUNCTION; Schema: hrms; Owner: -
--

CREATE FUNCTION hrms.fn_resolve_payroll_variable(p_variable_id bigint, p_employee_id bigint, p_calc_date date DEFAULT CURRENT_DATE) RETURNS numeric
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
	v_var RECORD;
	v_value numeric(15,4);
BEGIN
	SELECT * INTO v_var FROM hrms.payroll_variable WHERE id = p_variable_id;
	IF NOT FOUND THEN
		RAISE EXCEPTION 'ไม่พบตัวแปร id = %', p_variable_id;
	END IF;

	IF v_var.source_type = 'CONSTANT' THEN
		SELECT pvv.numeric_value INTO v_value
		FROM hrms.payroll_variable_value pvv
		WHERE pvv.variable_id = p_variable_id
		  AND pvv.status = 'ACTIVE'
		  AND pvv.effective_from <= p_calc_date
		  AND (pvv.effective_to IS NULL OR pvv.effective_to >= p_calc_date)
		ORDER BY pvv.effective_from DESC
		LIMIT 1;

	ELSE -- DERIVED
		CASE v_var.source_ref

			WHEN 'EMPLOYEE_BASE_SALARY' THEN
				SELECT base_salary INTO v_value
				FROM hrms.employee_salary
				WHERE employee_id = p_employee_id
				  AND effective_from <= p_calc_date
				  AND (effective_to IS NULL OR effective_to >= p_calc_date)
				ORDER BY effective_from DESC LIMIT 1;

			WHEN 'EMPLOYEE_DAILY_RATE' THEN
				-- คำนวณอัตราต่อวัน (ฐานเงินเดือน / 30)
				SELECT base_salary / 30.0 INTO v_value
				FROM hrms.employee_salary
				WHERE employee_id = p_employee_id
				  AND effective_from <= p_calc_date
				  AND (effective_to IS NULL OR effective_to >= p_calc_date)
				ORDER BY effective_from DESC LIMIT 1;

			WHEN 'EMPLOYEE_HOURLY_RATE' THEN
				-- คำนวณอัตราต่อชั่วโมง (ฐานเงินเดือน / 30 วัน / 8 ชม.)
				SELECT base_salary / 30.0 / 8.0 INTO v_value
				FROM hrms.employee_salary
				WHERE employee_id = p_employee_id
				  AND effective_from <= p_calc_date
				  AND (effective_to IS NULL OR effective_to >= p_calc_date)
				ORDER BY effective_from DESC LIMIT 1;

			WHEN 'ATTENDANCE_ACTUAL_WORK_DAYS' THEN
				-- นับเฉพาะวันที่เข้างานจริงในรอบเดือน
				SELECT COUNT(*) INTO v_value
				FROM hrms.attendance_daily
				WHERE employee_id = p_employee_id
				  AND EXTRACT(YEAR FROM work_date) = EXTRACT(YEAR FROM p_calc_date)
				  AND EXTRACT(MONTH FROM work_date) = EXTRACT(MONTH FROM p_calc_date)
				  AND (worked_minutes > 0 OR status = 'PRESENT');

			WHEN 'ATTENDANCE_SHIFT_COUNT' THEN
				-- นับจำนวนกะที่เข้าทำงานจริงในรอบเดือน
				SELECT COUNT(*) INTO v_value
				FROM hrms.attendance_daily
				WHERE employee_id = p_employee_id
				  AND EXTRACT(YEAR FROM work_date) = EXTRACT(YEAR FROM p_calc_date)
				  AND EXTRACT(MONTH FROM work_date) = EXTRACT(MONTH FROM p_calc_date)
				  AND shift_id IS NOT NULL
				  AND (worked_minutes > 0 OR status = 'PRESENT');

			ELSE
				RAISE EXCEPTION 'ไม่รู้จัก source_ref = %', v_var.source_ref;
		END CASE;
	END IF;

	RETURN COALESCE(v_value, 0);
END;
$$;


