BEGIN
    SELECT wage_type INTO v_wage_type
    FROM hrms.employment_contract
    WHERE employee_id = NEW.employee_id
      AND status = 'ACTIVE'
    ORDER BY start_date DESC
    LIMIT 1;

    NEW.wage_type := COALESCE(v_wage_type, 'MONTHLY');
    RETURN NEW;
END;
$$;


--
-- Name: generate_attendance_monthly_summary(integer, integer); Type: FUNCTION; Schema: hrms; Owner: -
--

CREATE FUNCTION hrms.generate_attendance_monthly_summary(p_year integer, p_month integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
         total_work_days, total_worked_minutes,
         total_late_minutes, total_early_leave_minutes,
         total_absent_days,
         generated_at)
    SELECT
        employee_id,
        p_year,
        p_month,
        COUNT(*)                              AS total_work_days,
        COALESCE(SUM(worked_minutes), 0)      AS total_worked_minutes,
        COALESCE(SUM(late_minutes), 0)        AS total_late_minutes,
        COALESCE(SUM(early_leave_minutes), 0) AS total_early_leave_minutes,
        COUNT(*) FILTER (WHERE absent = true) AS total_absent_days,
        now()
    FROM hrms.attendance_daily
    WHERE EXTRACT(YEAR  FROM work_date) = p_year
      AND EXTRACT(MONTH FROM work_date) = p_month
    GROUP BY employee_id
    ON CONFLICT (employee_id, year, month)
    DO UPDATE SET
        total_work_days           = EXCLUDED.total_work_days,
        total_worked_minutes      = EXCLUDED.total_worked_minutes,
        total_late_minutes        = EXCLUDED.total_late_minutes,
        total_early_leave_minutes = EXCLUDED.total_early_leave_minutes,
        total_absent_days         = EXCLUDED.total_absent_days,
        generated_at              = now();
END;
$$;


--
-- Name: generate_department_headcount_snapshot(date); Type: FUNCTION; Schema: hrms; Owner: -
--

CREATE FUNCTION hrms.generate_department_headcount_snapshot(p_snapshot_date date DEFAULT CURRENT_DATE) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    SELECT ea.department_id, p_snapshot_date, COUNT(DISTINCT ea.employee_id)
    FROM hrms.employee_assignment ea
    WHERE ea.effective_from <= p_snapshot_date
      AND (ea.effective_to IS NULL OR ea.effective_to >= p_snapshot_date)
    GROUP BY ea.department_id
    ON CONFLICT (department_id, snapshot_date)
    DO UPDATE SET headcount = EXCLUDED.headcount;
END;
$$;


--
-- Name: generate_leave_balance_new_year(integer); Type: FUNCTION; Schema: hrms; Owner: -
--

CREATE FUNCTION hrms.generate_leave_balance_new_year(p_year integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_prev_year int4 := p_year - 1;
    v_bal RECORD;
    v_policy RECORD;
    v_carry numeric(8,2);
    v_entitlement numeric(8,2);
    v_new_balance_id int8;
BEGIN
    FOR v_bal IN
        SELECT lb.employee_id, lb.leave_type_id, lb.remaining_days
        FROM hrms.leave_balance lb
        WHERE lb.year = v_prev_year
    LOOP
        SELECT lp.* INTO v_policy
        FROM hrms.leave_policy lp
        JOIN hrms.employee_assignment ea
            ON ea.employee_id = v_bal.employee_id
            AND ea.is_current = true
        WHERE lp.leave_type_id = v_bal.leave_type_id
          AND (lp.level_id IS NULL OR lp.level_id = ea.level_id)
          AND lp.effective_from <= make_date(p_year, 1, 1)
          AND (lp.effective_to IS NULL OR lp.effective_to >= make_date(p_year, 1, 1))
        ORDER BY lp.level_id NULLS LAST, lp.effective_from DESC
        LIMIT 1;

        IF v_policy IS NULL OR NOT v_policy.carry_forward_allowed THEN
            v_carry := 0;
        ELSE
            v_carry := GREATEST(v_bal.remaining_days, 0);
            IF v_policy.carry_forward_max_days IS NOT NULL THEN
                v_carry := LEAST(v_carry, v_policy.carry_forward_max_days);
            END IF;
        END IF;

        v_entitlement := COALESCE(v_policy.entitlement_days, 0);

             carried_forward, used_days, adjusted_days, remaining_days, carry_forward_expiry)
        VALUES
            (v_bal.employee_id, v_bal.leave_type_id, p_year, 0, v_entitlement,
             v_carry, 0, 0, v_entitlement + v_carry,
             CASE WHEN v_policy.carry_forward_expiry_days IS NOT NULL
                  THEN make_date(p_year, 1, 1) + v_policy.carry_forward_expiry_days
                  ELSE NULL END)
        ON CONFLICT (employee_id, leave_type_id, year) DO NOTHING
        RETURNING balance_id INTO v_new_balance_id;

        IF v_new_balance_id IS NOT NULL THEN
            IF v_carry > 0 THEN
                     'ยกยอดวันลาคงเหลือจากปี ' || v_prev_year);
            END IF;
            IF v_entitlement > 0 THEN
                     'สิทธิ์วันลาประจำปี ' || p_year);
            END IF;
        END IF;
    END LOOP;
END;
$$;


--
-- Name: generate_turnover_monthly(integer, integer); Type: FUNCTION; Schema: hrms; Owner: -
--

CREATE FUNCTION hrms.generate_turnover_monthly(p_year integer, p_month integer) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_period_start date := make_date(p_year, p_month, 1);
    v_period_end date := (make_date(p_year, p_month, 1) + INTERVAL '1 month')::date;
BEGIN
    SELECT
        ea.department_id,
        p_year,
        p_month,
        COUNT(*) FILTER (WHERE ec.start_date >= v_period_start AND ec.start_date < v_period_end) AS joined_count,
        COUNT(*) FILTER (WHERE ec.termination_date >= v_period_start AND ec.termination_date < v_period_end) AS resigned_count,
        ROUND(
            COUNT(*) FILTER (WHERE ec.termination_date >= v_period_start AND ec.termination_date < v_period_end)::numeric
            / NULLIF(COUNT(DISTINCT ea.employee_id), 0) * 100
        , 2) AS turnover_rate
    FROM hrms.employee_assignment ea
    JOIN hrms.employment_contract ec ON ec.employee_id = ea.employee_id
    WHERE ea.effective_from <= v_period_end
      AND (ea.effective_to IS NULL OR ea.effective_to >= v_period_start)
    GROUP BY ea.department_id
    ON CONFLICT (department_id, year, month)
    DO UPDATE SET
        joined_count   = EXCLUDED.joined_count,
        resigned_count = EXCLUDED.resigned_count,
        turnover_rate  = EXCLUDED.turnover_rate;
END;
$$;


--
-- Name: set_payroll_snapshot(); Type: FUNCTION; Schema: hrms; Owner: -
--

CREATE FUNCTION hrms.set_payroll_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_assign RECORD;
    v_period RECORD;
    v_emp RECORD;
BEGIN
    SELECT * INTO v_period FROM hrms.payroll_period WHERE id = NEW.period_id;

    SELECT prefix || ' ' || first_name || ' ' || last_name AS full_name
    INTO v_emp
    FROM hrms.employee WHERE id = NEW.employee_id;

    SELECT ea.department_id, ea.position_id, ea.wage_type,
           d.department_name, p.position_name
    INTO v_assign
    FROM hrms.employee_assignment ea
    JOIN hrms.department d ON d.id = ea.department_id
    JOIN hrms."position" p  ON p.id  = ea.position_id
    WHERE ea.employee_id = NEW.employee_id
      AND ea.effective_from <= v_period.end_date
      AND (ea.effective_to IS NULL OR ea.effective_to >= v_period.start_date)
    ORDER BY ea.effective_from DESC
    LIMIT 1;

    IF NEW.snapshot_employee_name IS NULL THEN
        NEW.snapshot_employee_name := v_emp.full_name;
    END IF;

    IF NEW.snapshot_department_name IS NULL THEN
        NEW.snapshot_department_name := v_assign.department_name;
    END IF;

    IF NEW.snapshot_position_name IS NULL THEN
        NEW.snapshot_position_name := v_assign.position_name;
    END IF;

    IF NEW.snapshot_wage_type IS NULL THEN
        NEW.snapshot_wage_type := COALESCE(v_assign.wage_type, 'MONTHLY');
    END IF;

    RETURN NEW;
END;
$$;


