--
-- Name: sync_document_status_from_approval(); Type: FUNCTION; Schema: hrms; Owner: -
--

CREATE FUNCTION hrms.sync_document_status_from_approval() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_leave RECORD;
    v_resignation RECORD;
BEGIN
    CASE NEW.document_type
        WHEN 'ATTENDANCE_ADJUSTMENT' THEN
            UPDATE hrms.attendance_adjustment
            SET status      = NEW.status,
                reviewed_at = NEW.completed_at
            WHERE approval_instance_id = NEW.id;

        WHEN 'LEAVE_REQUEST' THEN
            UPDATE hrms.leave_request
            SET status = NEW.status
            WHERE id = NEW.source_document_id;

        WHEN 'RESIGNATION_REQUEST' THEN
            UPDATE hrms.resignation_request
            SET status = NEW.status
            WHERE id = NEW.source_document_id;

            IF NEW.status = 'APPROVED' THEN
                SELECT * INTO v_resignation FROM hrms.resignation_request WHERE id = NEW.source_document_id;

                UPDATE hrms.employment_contract
                SET termination_date   = v_resignation.requested_last_working_date,
                    termination_reason = v_resignation.reason,
                    status             = 'TERMINATED'
                WHERE employee_id = v_resignation.employee_id
                  AND status = 'ACTIVE';

                     'RESIGNED',
                     v_resignation.requested_last_working_date + 1,
                     'Resignation approved: ' || COALESCE(v_resignation.reason, ''),
                     v_resignation.resulting_contract_id);
            END IF;

        WHEN 'PAYROLL_PERIOD' THEN
            UPDATE hrms.payroll_period
            SET status = CASE
                WHEN NEW.status = 'APPROVED' THEN 'CLOSED'
                WHEN NEW.status = 'REJECTED' THEN 'DRAFT'
                ELSE status
            END
            WHERE id = NEW.source_document_id;

        ELSE
            NULL;
    END CASE;

    RETURN NEW;
END;
$$;


--
-- Name: sync_employee_status_history(); Type: FUNCTION; Schema: hrms; Owner: -
--

CREATE FUNCTION hrms.sync_employee_status_history() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_status varchar(30);
BEGIN
    IF TG_OP = 'INSERT' THEN
        v_status := CASE 
            WHEN NEW.contract_type = 'PROBATION' THEN 'PROBATION'
            WHEN NEW.contract_type = 'PERMANENT' THEN 'PERMANENT'
            WHEN NEW.contract_type = 'FIXED_TERM' THEN 'FIXED_TERM'
            WHEN NEW.status = 'TERMINATED' THEN 'TERMINATED'
            ELSE 'OTHER'
        END;

    END IF;

    RETURN NEW;
END;
$$;


