--

CREATE TABLE hrms.employee_benefit_claim (
    id bigint NOT NULL,
    employee_id bigint NOT NULL,
    benefit_item_id bigint NOT NULL,
    claim_year integer DEFAULT EXTRACT(year FROM CURRENT_DATE) NOT NULL,
    claim_date date DEFAULT CURRENT_DATE NOT NULL,
    amount numeric(12,2) NOT NULL,
    receipt_number character varying(100),
    service_provider character varying(200),
    remarks text,
    status character varying(20) DEFAULT 'APPROVED'::character varying NOT NULL,
    approved_by_user_id bigint,
    approved_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    attachment_file_name character varying(255),
    attachment_url text,
    payment_status character varying(20),
    payroll_period_id bigint,
    paid_at timestamp with time zone,
    request_no character varying(30),
    approval_instance_id bigint,
    requested_by_employee_id bigint,
    approved_by_employee_id bigint,
    reject_reason text,
    completed_at timestamp with time zone,
    file_name character varying(255),
    file_mime_type character varying(100),
    file_size bigint,
    file_data bytea
);


