    status character varying(20) DEFAULT 'ACTIVE'::character varying NOT NULL,
    CONSTRAINT social_security_rate_effective_check CHECK (((effective_to IS NULL) OR (effective_to >= effective_from))),
    CONSTRAINT social_security_rate_pct_check CHECK (((employee_contribution_percent >= (0)::numeric) AND (employee_contribution_percent <= (100)::numeric) AND (employer_contribution_percent >= (0)::numeric) AND (employer_contribution_percent <= (100)::numeric))),
    CONSTRAINT social_security_rate_status_check CHECK (((status)::text = ANY (ARRAY[('ACTIVE'::character varying)::text, ('INACTIVE'::character varying)::text]))),
    CONSTRAINT social_security_rate_wage_check CHECK ((max_wage_base_amount >= min_wage_base_amount))
);


--
-- Name: TABLE social_security_rate; Type: COMMENT; Schema: hrms; Owner: -
--

COMMENT ON TABLE hrms.social_security_rate IS 'อัตราการคำนวณเงินสมทบกองทุนประกันสังคม (เพดานเงินเดือน, เปอร์เซ็นต์สมทบลูกจ้างและนายจ้าง)';


--
-- Name: social_security_rate_rate_id_seq; Type: SEQUENCE; Schema: hrms; Owner: -
--

ALTER TABLE hrms.social_security_rate ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME hrms.social_security_rate_rate_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


--
-- Name: tax_bracket; Type: TABLE; Schema: hrms; Owner: -
--

CREATE TABLE hrms.tax_bracket (
    id bigint NOT NULL,
    bracket_name character varying(100) NOT NULL,
    income_from numeric(15,2) NOT NULL,
    income_to numeric(15,2),
    tax_rate numeric(5,2) NOT NULL,
    base_tax_amount numeric(15,2) DEFAULT 0 NOT NULL,
    effective_from date NOT NULL,
    effective_to date,
    status character varying(20) DEFAULT 'ACTIVE'::character varying NOT NULL,
    CONSTRAINT tax_bracket_effective_check CHECK (((effective_to IS NULL) OR (effective_to >= effective_from))),
    CONSTRAINT tax_bracket_range_check CHECK (((income_to IS NULL) OR (income_to > income_from))),
    CONSTRAINT tax_bracket_rate_check CHECK (((tax_rate >= (0)::numeric) AND (tax_rate <= (100)::numeric))),
    CONSTRAINT tax_bracket_status_check CHECK (((status)::text = ANY (ARRAY[('ACTIVE'::character varying)::text, ('INACTIVE'::character varying)::text])))
);


--
-- Name: TABLE tax_bracket; Type: COMMENT; Schema: hrms; Owner: -
--

COMMENT ON TABLE hrms.tax_bracket IS 'ตาราง Master บัญชีอัตราภาษีเงินได้บุคคลธรรมดาแบบขั้นบันไดตามกฎหมายสรรพากร';


--
-- Name: tax_bracket_tax_bracket_id_seq; Type: SEQUENCE; Schema: hrms; Owner: -
--

ALTER TABLE hrms.tax_bracket ALTER COLUMN id ADD GENERATED BY DEFAULT AS IDENTITY (
    SEQUENCE NAME hrms.tax_bracket_tax_bracket_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1
);


