    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    salary_pin_hash character varying(255),
    CONSTRAINT user_account_status_check CHECK (((status)::text = ANY (ARRAY[('ACTIVE'::character varying)::text, ('INACTIVE'::character varying)::text, ('LOCKED'::character varying)::text])))
);


--
-- Name: TABLE user_account; Type: COMMENT; Schema: hrms; Owner: -
--

COMMENT ON TABLE hrms.user_account IS 'บัญชีผู้ใช้งานระบบ (Username, รหัสผ่านแบบ Hash, สถานะเปิดใช้งาน, ผูกกับรหัสพนักงาน)';


